#pragma once
static const char piko_keymap_html[] =
"<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>PIKO Key Mapper</title>\n"
"<style>body{background:#101722;color:#e9eff7;font:15px system-ui;margin:0}main{max-width:920px;margin:35px auto;padding:20px}a{color:#71caff}button,input{font:inherit;padding:10px;border:1px solid #64758b;border-radius:7px;background:#22354b;color:white}button{cursor:pointer}button:disabled{opacity:.5}table{width:100%;border-collapse:collapse;background:#1b2636}th,td{padding:12px;border-bottom:1px solid #3a4b62;text-align:left}input{width:90%;box-sizing:border-box}pre{white-space:pre-wrap;background:#070e19;padding:12px;border-radius:9px;max-height:40vh;overflow:auto}.active{color:#70edb1}</style>\n"
"<main><a href=\"/#diag\">← Diag</a><h1>Key mapping scan</h1><p>Type the physical key, press Start scan, press and release that key once, then Save reading. Sampling runs on the ESP32 every 10 ms. Try STOP and rotary separately.</p>\n"
"<div id=\"status\">Ready</div><table><thead><tr><th>Physical key</th><th>Observed inputs / changes</th><th>Action</th></tr></thead><tbody id=\"body\"></tbody></table>\n"
"<p><button id=\"add\">Add row</button> <button id=\"report\">Generate report & copy</button> <button id=\"clear\">Clear mapping</button></p><pre id=\"output\">No report yet.</pre>\n"
"<script>\n"
"const rows=[26,14,27],cols=[32,33,34];const tbody=document.querySelector('#body'),state={active:-1};\n"
"let records=JSON.parse(localStorage.getItem('piko-keymap-v2')||'null')||Array.from({length:16},(_,i)=>({key:i<10?String(i):i===10?'STOP':i===11?'Rotary press':i===12?'Rotary left':i===13?'Rotary right':'',value:'',data:null}));\n"
"function persist(){localStorage.setItem('piko-keymap-v2',JSON.stringify(records))}\n"
"function decode(d){if(!d)return 'Not scanned';const parts=[];for(let i=0;i<9;i++){if((d.rawChanged||0)&(1<<i))parts.push('RAW R'+(Math.floor(i/3)+1)+'C'+(i%3+1)+' GPIO'+rows[Math.floor(i/3)]+'→'+cols[i%3]);if((d.matrixChanged||0)&(1<<i))parts.push('KEY R'+(Math.floor(i/3)+1)+'C'+(i%3+1));}['GPIO2','GPIO15','GPIO12','GPIO13'].forEach((n,i)=>{if(d.pinsChanged&(1<<i))parts.push(n+' changed')});if(d.rotaryDelta)parts.push('Rotary delta '+d.rotaryDelta);if(d.idleChanged)parts.push('Idle column bits changed '+d.idleChanged);if(!parts.length)parts.push('No input change detected');return parts.join(', ')+' (samples '+d.samples+')'}\n"
"function render(){tbody.replaceChildren();records.forEach((r,i)=>{const tr=document.createElement('tr'),key=document.createElement('td'),val=document.createElement('td'),act=document.createElement('td');const input=document.createElement('input');input.value=r.key;input.placeholder='Button name';input.oninput=()=>{records[i].key=input.value;persist()};key.append(input);val.textContent=r.value||'—';const b=document.createElement('button');b.textContent=state.active===i?'Save reading':'Start scan';b.disabled=state.active!==-1&&state.active!==i;b.onclick=()=>scan(i);act.append(b);tr.append(key,val,act);tbody.append(tr)})}\n"
"async function scan(i){try{if(state.active===i){const res=await fetch('/api/capture/stop',{method:'POST'});if(!res.ok)throw Error('Stop HTTP '+res.status);records[i].data=await res.json();records[i].value=decode(records[i].data);state.active=-1;document.querySelector('#status').textContent='Saved: '+records[i].key;persist()}else if(state.active===-1){const res=await fetch('/api/capture/start',{method:'POST'});if(!res.ok)throw Error('Start HTTP '+res.status);state.active=i;document.querySelector('#status').textContent='Recording '+records[i].key+' — press and release physical key, then Save reading'}render()}catch(e){document.querySelector('#status').textContent='Error: '+e.message}}\n"
"document.querySelector('#add').onclick=()=>{records.push({key:'',value:'',data:null});persist();render()};\n"
"document.querySelector('#clear').onclick=()=>{if(confirm('Clear all mappings?')){records=[];persist();render()}};\n"
"document.querySelector('#report').onclick=async()=>{const output=['PIKO physical key to input report','Firmware scan: 10ms samples','Key | Observed changes'];records.forEach(r=>{if(r.key.trim())output.push(r.key+' | '+(r.value||'not scanned'))});const report=output.join('\\n');document.querySelector('#output').textContent=report;try{await navigator.clipboard.writeText(report);document.querySelector('#status').textContent='Report copied to clipboard'}catch(e){document.querySelector('#status').textContent='Copy unavailable; select report text below'}};\n"
"render();\n"
"</script></main></html>\n";
